import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();

  // Plane geometry (size 1x1, can be scaled later)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously, apply when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.intent?.visualSpec?.colors?.paper) || '#e8ecf2',
      align: 'center',
    });
    // Slightly offset in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives if any
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // GSAP timelines storage
  const timelines = [];

  // Interaction handlers
  root.userData.handlers = {
    hover: () => {
      const tl = gsap.to(plane.position, {
        y: plane.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      timelines.push(tl);
    },
    click: () => {
      const tl = gsap.to(plane.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      });
      timelines.push(tl);
      ctx.emit('navigate', { to: 'hub-journal' });
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    material.dispose();
    geometry.dispose();
  };

  return root;
}
